#include <stdio.h>
#include <stdlib.h>

FILE *open_file(const char *path, const char *mode) {
    FILE *file = fopen(path, mode);
    if (!file) { perror(path); exit(1); }
    return file;
}
void show_file(const char *path) {
    FILE *file = open_file(path, "r");
    int ch;
    while ((ch = fgetc(file)) != EOF) putchar(ch);
    fclose(file);
}
void copy_file(const char *source, const char *target) {
    FILE *in = open_file(source, "rb"), *out = open_file(target, "wb");
    int ch;
    while ((ch = fgetc(in)) != EOF) fputc(ch, out);
    fclose(in); fclose(out);
}

typedef struct { int num; char name[32]; double score[3], average; } Student;
Student read_student(FILE *file) {
    Student s;
    if (fscanf(file, "%d%31s%lf%lf%lf%lf", &s.num, s.name, &s.score[0], &s.score[1], &s.score[2], &s.average) != 6) exit(1);
    return s;
}
void write_student(FILE *file, Student s) {
    fprintf(file, "%d %s %.2f %.2f %.2f %.2f\n", s.num, s.name, s.score[0], s.score[1], s.score[2], s.average);
}
int before(Student a, Student b) {
    return a.average > b.average || (a.average == b.average && a.num < b.num);
}

int main(void) {
    int n;
    Student students[101], inserted;
    scanf("%d", &n);
    FILE *file = open_file("stu_sort", "w");
    for (int i = 0; i < n; i++) write_student(file, read_student(stdin));
    fclose(file);
    scanf("%d%31s%lf%lf%lf", &inserted.num, inserted.name, &inserted.score[0], &inserted.score[1], &inserted.score[2]);
    inserted.average = (inserted.score[0] + inserted.score[1] + inserted.score[2]) / 3;
    file = open_file("stu_sort", "r");
    for (int i = 0; i < n; i++) students[i] = read_student(file);
    fclose(file);
    int position = n;
    while (position > 0 && before(inserted, students[position - 1])) {
        students[position] = students[position - 1]; position--;
    }
    students[position] = inserted;
    file = open_file("stu_insert", "w");
    for (int i = 0; i <= n; i++) write_student(file, students[i]);
    fclose(file);
    show_file("stu_insert");
    return 0;
}
